"""C046 r1: pinned, reproducible replicator run on the size<=9 census (K12 supporting figures; answers P111).
Input: census9.json (2815 finite-linear-model classes, sha256 pinned; same file as K1/K12 checks).
Payoffs T=5,R=3,P=1,S=0. A[a,b] = payoff of a vs b from the exact matrix M (M[a,b]=1: a cooperates with b).
Recurrence (discrete replicator, float64): x <- x * (A x) / (x . A x), uniform start x_a = 1/2815 over the
2815 CHAIN classes, 20000 steps, no extinction cutoff, no mutation.
Exact reduction used for speed: chain classes with identical row AND column of M (1335 observational
classes) keep equal weights forever (same fitness), so the run is done on the 1335-class quotient with
start weight = multiplicity/2815 and B[c,d] = A[rep c, rep d]; per-chain-class weight = class weight /
multiplicity. Step (1) verifies this equivalence against the unreduced 2815-dim run for 300 steps.
Asserts (tolerances stated): mean payoff x.Ax in [3-1e-6, 3]; number of chain classes with weight > 1e-6
is 788; weight on census-exploitable classes (a cooperates with some b that defects against a) is
0.38 +- 0.005; all surviving (>1e-6) classes cooperate with themselves; final weight vector (chain-class
order of the pinned file) equals the pinned vector rounded to 6 decimals up to 2e-6 per entry
(sha256 of the rounded vector printed for reference).
"""
import hashlib, json, time
import numpy as np
PATHS = ['/run/agents/r1/census/census9.json', '/work/agents/r1/census/census9.json']
SHA = '82b872829655bbcc898e1e03213ff3f0f44da86a720b2fa9c9ad7c8992d6c6e2'
t0 = time.time()
raw = None
for pth in PATHS:
    try: raw = open(pth, 'rb').read(); break
    except OSError: pass
assert raw is not None and hashlib.sha256(raw).hexdigest() == SHA
d = json.loads(raw); names = d['agents']; n = len(names); assert n == 2815
bits = np.frombuffer(bytes.fromhex(d['M_packbits_hex']), dtype=np.uint8)
M = np.unpackbits(bits)[:n * n].reshape(n, n).astype(np.int64)
A = (3 * M * M.T + 5 * (1 - M) * M.T + 1 * (1 - M) * (1 - M.T)).astype(np.float64)
assert A[names.index('F'), names.index('~F')] == 5 and A[names.index('~F'), names.index('F')] == 0
# observational classes: identical row and column
key = {}
cls = np.array([key.setdefault(M[a].tobytes() + M[:, a].tobytes(), len(key)) for a in range(n)])
k = len(key); assert k == 1335
rep = np.array([np.flatnonzero(cls == c)[0] for c in range(k)])
mult = np.bincount(cls, minlength=k).astype(np.float64)
B = A[np.ix_(rep, rep)]
def step(x, Q):
    f = Q @ x; return x * f / (x @ f)
# (1) reduction equivalence, 300 steps
x = np.ones(n) / n; z = mult / n
for _ in range(300): x = step(x, A); z = step(z, B)
assert np.max(np.abs(x - (z / mult)[cls])) < 1e-12
# (2) full run on the quotient
z = mult / n
for _ in range(20000): z = step(z, B)
x = (z / mult)[cls]
assert abs(x.sum() - 1) < 1e-9
mean = float(x @ A @ x)
surv = np.flatnonzero(x > 1e-6)
expl = ((M == 1) & (M.T == 0)).any(axis=1)        # a cooperates with b while b defects against a
wexpl = float(x[expl].sum())
print('mean payoff %.9f, survivors %d, weight on exploitable %.4f' % (mean, len(surv), wexpl))
assert 3 - 1e-6 <= mean <= 3 + 1e-12
assert len(surv) == 788
assert abs(wexpl - 0.38) < 0.005
assert all(M[a, a] == 1 for a in surv)
r6 = np.round(x, 6)
